toolApi.validaEMontaPedido:
const e = $input.first().json;
const ROTAS = ['resumo','despesas','lancamentos','categorias','vencimentos','orcamento','orcamento/definir','opcoes','acoes/preparar','acoes/confirmar','acoes/cancelar','vinculo/confirmar','vinculo/status','notificacoes/parar'];
const telefone = String(e.telefone || '').trim();
const accountId = Number(e.accountId);
const rota = String(e.rota || '').trim();
if (!/^\+[1-9]\d{7,14}$/.test(telefone)) throw new Error('Telefone invalido.');
if (!Number.isSafeInteger(accountId) || accountId <= 0) throw new Error('Conta invalida.');
if (!ROTAS.includes(rota)) throw new Error('Rota nao permitida.');
const parse = (v) => {
  if (v && typeof v === 'object') return v;
  if (v && String(v).trim()) { try { return JSON.parse(String(v)); } catch { throw new Error('Parametros devem ser JSON valido.'); } }
  return {};
};
let params = parse(e.parametros);
if (!params || typeof params !== 'object' || Array.isArray(params)) params = {};
if (typeof params.dados === 'string') {
  const d = parse(params.dados);
  params.dados = d && typeof d === 'object' && !Array.isArray(d) ? d : {};
}
// Remove campos vazios enviados pela IA
for (const k of Object.keys(params)) { if (params[k] === '' || params[k] === null) delete params[k]; }
// Telefone e conta sempre vem do fluxo, nunca da IA.
delete params.telefone; delete params.accountId; delete params.uid; delete params.owner_uid;
return [{ json: { rota, body: { ...params, telefone, accountId } } }];

toolApi.formataResposta:
const r = $input.first().json;
const status = Number(r.statusCode || 0);
const body = r.body && typeof r.body === 'object' ? r.body : {};
if (status >= 200 && status < 300) return [{ json: { ok: true, dados: body } }];
const erro = body.erro || { codigo: 'HTTP_' + status, mensagem: 'Falha ao consultar o sistema.' };
return [{ json: { ok: false, erro } }];
